import{_ as c,C as d,o as s,c as i,a2 as a,E as e}from"./chunks/framework.TaNiW7i8.js";const v=JSON.parse('{"title":"Écrire dans la mémoire","description":"","frontmatter":{"title":"Écrire dans la mémoire"},"headers":[],"relativePath":"agent/ecrire.md","filePath":"agent/ecrire.md"}'),l={name:"agent/ecrire.md"};function u(m,o,p,h,f,g){const t=d("AskExample"),r=d("Ask"),n=d("Capture");return s(),i("div",null,[o[0]||(o[0]=a('<h1 id="ecrire-dans-la-memoire" tabindex="-1">Écrire dans la mémoire <a class="header-anchor" href="#ecrire-dans-la-memoire" aria-label="Permalink to &quot;Écrire dans la mémoire&quot;">​</a></h1><p>Ce parcours sert à faire entrer dans la mémoire un fait, un principe, un objectif, une personne ou un document : l&#39;agent crée une <strong>note</strong> (un « atome ») dans la bonne zone. Pour ce que la session elle-même laisse, voir <a href="/Kessho/agent/archiver.html">Archiver une session</a>.</p><h2 id="ce-que-vous-demandez-a-l-agent" tabindex="-1">Ce que vous demandez à l&#39;agent <a class="header-anchor" href="#ce-que-vous-demandez-a-l-agent" aria-label="Permalink to &quot;Ce que vous demandez à l&#39;agent&quot;">​</a></h2>',3)),e(t,{tool:"mem_note"}),e(t,{tool:"mem_principle"}),e(t,{tool:"mem_goal"}),e(t,{tool:"mem_person"}),e(t,{tool:"mem_doc"}),e(r,{say:"Garde ça de côté, je classerai plus tard : penser à demander un devis pour le rail LED.",verb:"mem",family:"ingestion",args:'{"content":"Penser à demander un devis pour le rail LED.","hint":"idea"}'}),o[1]||(o[1]=a('<p>Quand vous ne dites pas de quelle nature est le contenu (« note ceci », « garde ça »), l&#39;agent peut passer par <code>mem</code>, qui dépose dans la boîte de réception ; quand vous la précisez (« retiens ce principe »), il appelle l&#39;outil de ce type.</p><h2 id="ce-que-fait-l-agent" tabindex="-1">Ce que fait l&#39;agent <a class="header-anchor" href="#ce-que-fait-l-agent" aria-label="Permalink to &quot;Ce que fait l&#39;agent&quot;">​</a></h2><p>Chaque outil <strong>écrit une nouvelle note</strong> :</p><table tabindex="0"><thead><tr><th>Outil</th><th>Où elle arrive</th><th>Obligatoire</th><th>Utile à savoir</th></tr></thead><tbody><tr><td><a href="/Kessho/reference/mcp/ingestion.html#mem"><code>mem</code></a></td><td><code>00-inbox/</code></td><td><code>content</code></td><td><code>hint</code> oriente le classement ultérieur : <code>note</code>, <code>principle</code>, <code>goal</code>, <code>person</code> ou <code>idea</code>.</td></tr><tr><td><a href="/Kessho/reference/mcp/ingestion.html#mem-note"><code>mem_note</code></a></td><td><code>20-knowledge/</code></td><td><code>title</code>, <code>content</code></td><td><code>title</code> sert de nom.</td></tr><tr><td><a href="/Kessho/reference/mcp/ingestion.html#mem-principle"><code>mem_principle</code></a></td><td><code>40-principles/{portée}/</code></td><td><code>title</code>, <code>content</code></td><td><code>force</code> : <code>red-line</code>, <code>heuristic</code> (défaut), <code>value</code> ou <code>action-rule</code>.</td></tr><tr><td><a href="/Kessho/reference/mcp/ingestion.html#mem-goal"><code>mem_goal</code></a></td><td><code>50-goals/{horizon}/</code></td><td><code>title</code></td><td><code>horizon</code> : <code>short</code> (défaut), <code>medium</code> ou <code>long</code> ; <code>status</code> : <code>open</code> (défaut), <code>in-progress</code>, <code>done</code> ou <code>abandoned</code> ; <code>deadline</code> au format AAAA-MM-JJ.</td></tr><tr><td><a href="/Kessho/reference/mcp/ingestion.html#mem-person"><code>mem_person</code></a></td><td><code>60-people/{relation}/</code></td><td><code>name</code></td><td><code>relation</code> : <code>colleague</code> (défaut), <code>client</code>, <code>friend</code>, <code>family</code> ou <code>other</code>. La fiche est marquée <strong>sensible</strong> par défaut (<code>sensitive</code>).</td></tr><tr><td><a href="/Kessho/reference/mcp/ingestion.html#mem-doc"><code>mem_doc</code></a></td><td><code>00-inbox/</code></td><td><code>path</code> (absolu)</td><td>Un document local par appel : Markdown, texte, PDF, DOCX, XLSX, PPTX, HTML ou CSV.</td></tr></tbody></table><p>Tous sauf <code>mem</code> acceptent <code>project</code> (projet de rattachement) et <code>scope</code> : <code>work</code> (défaut), <code>personal</code> ou <code>all</code>.</p><p><strong>Aucune de ces écritures n&#39;écrase une note existante.</strong> Si le nom est déjà pris, le serveur en choisit un autre en ajoutant un suffixe (<code>-2</code>, <code>-3</code>…) ; la réponse donne le chemin réellement écrit. L&#39;agent n&#39;a donc pas à vérifier d&#39;abord si la note existe. Quand l&#39;écriture tombe dans une zone transverse, l&#39;<code>index.md</code> de cette zone est régénéré.</p><p>D&#39;autres outils écrivent des notes, avec leur propre règle :</p><ul><li><a href="/Kessho/reference/mcp/session.html#mem-archive"><code>mem_archive</code></a>, en mode complet, crée les notes de <code>derive</code> ; un nom déjà pris y fait <strong>refuser</strong> l&#39;archivage entier (voir <a href="/Kessho/agent/archiver.html">Archiver une session</a>).</li><li><a href="/Kessho/reference/mcp/ingestion.html#mem-codebase"><code>mem_codebase</code></a> inscrit à la carte d&#39;un projet un fait que le code ne dit pas de lui-même (<code>fact</code>, <code>body</code>, <code>project</code>). Il demande les fichiers que le fait décrit (<code>describes</code>, chemins relatifs au dépôt, qui doivent exister) ou, à défaut, <code>unmeasurable_because</code>, la raison pour laquelle il ne se rattache à aucun fichier ; sans l&#39;un des deux, l&#39;écriture est refusée. Le catalogue conseille de consulter d&#39;abord <a href="/Kessho/reference/mcp/maintenance.html#mem-codebase-scan"><code>mem_codebase_scan</code></a>.</li></ul><p>Corriger une note existante n&#39;est pas le rôle de ces outils : renommer, déplacer, rattacher ou retirer se fait avec ceux de <a href="/Kessho/agent/entretenir.html">Entretenir la mémoire</a>.</p><h2 id="ce-que-vous-voyez" tabindex="-1">Ce que vous voyez <a class="header-anchor" href="#ce-que-vous-voyez" aria-label="Permalink to &quot;Ce que vous voyez&quot;">​</a></h2>',10)),e(n,{name:"zone-liste",alt:"La zone Connaissance en liste, filtrée sur « Cette année » : une ligne par note, avec son type et son projet."}),o[2]||(o[2]=a('<p>La note écrite apparaît dans sa zone, ici <strong>Connaissance</strong> (<code>20-knowledge</code>) : une ligne par note, avec son type et son projet (voir <a href="/Kessho/guide/zones.html">Zones</a>). Le témoin de fraîcheur s&#39;allume dès que l&#39;agent écrit, et <strong>Relire</strong> met la liste à jour. Pour ouvrir la note et la lire ou la modifier, voir <a href="/Kessho/guide/atom.html">Atome et éditeur</a>.</p><p>Vous pouvez aussi créer une note vous-même, avec <strong>Nouveau</strong> dans l&#39;en-tête de la zone : l&#39;agent n&#39;est pas nécessaire.</p>',2))])}const b=c(l,[["render",u]]);export{v as __pageData,b as default};
